/**
 * Turn a string into a URL slug: lowercase, runs of non-alphanumerics become a
 * single hyphen, no leading or trailing hyphens.
 *
 * options.maxLength: if set, cut the slug to at most that many characters at
 * the last hyphen boundary (never splitting a word). If the first word alone
 * exceeds maxLength, the word itself is cut.
 */
export function slugify(input, options) {
  const slug = String(input)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');

  const maxLength = options && options.maxLength;
  if (maxLength == null || slug.length <= maxLength) return slug;
  if (maxLength <= 0) return '';

  // A word boundary exactly at maxLength means the first maxLength chars are whole words.
  const head = slug.slice(0, maxLength);
  if (slug[maxLength] === '-') return head;
  const cut = head.lastIndexOf('-');
  return (cut > 0 ? head.slice(0, cut) : head).replace(/-+$/, '');
}

